SINA_SMART["anat2-abdominal-wall"] = {"lecture":"anat2-abdominal-wall","title":"Abdominal wall and inguinal canal","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-abdominal-wall:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e0","text":"Rule of 3: skin, Camper's, Scarpa's / EO, IO, TA / transversalis fascia, extraperitoneal fat, peritoneum.","topic":"Anterolateral wall","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e2","text":"IO gives cremaster; IO + TA = conjoint tendon.","topic":"Anterolateral wall","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e3","text":"Rectus sheath; linea alba; arcuate line: no posterior sheath below.","topic":"Anterolateral wall","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e4","text":"Umbilical remnants: round ligament, median and medial umbilical ligaments.","topic":"Anterolateral wall","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e5","text":"Lymph above umbilicus → axillary; below → superficial inguinal.","topic":"Anterolateral wall","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e6","text":"Weak areas: umbilicus, linea semilunaris (Spigelian), incisions.","topic":"Anterolateral wall","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e1","text":"EO lower edge = inguinal ligament; aponeurosis = superficial ring.","topic":"Inguinal canal","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e7","text":"Inguinal canal: deep ring (transversalis fascia) → superficial ring (EO).","topic":"Inguinal canal","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e8","text":"Contents: spermatic cord / round ligament, ilio-inguinal nerve.","topic":"Inguinal canal","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e9","text":"Indirect hernia lateral, direct medial to inferior epigastric vessels.","topic":"Inguinal canal","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-abdominal-wall:e10","text":"Posterior wall: psoas, quadratus lumborum, iliacus, diaphragm.","topic":"Posterior wall","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"9rasgc":"a","fkn486":"a","1vdzvzu":"a","40v04e":"a","1m4ylji":"a","nlh76a":"a","kw8vmf":"a","6dczac":"a","1ndf0lk":"a","ek316v":"a","qacv87":"a","fuvnx8":"a","1q4hwdj":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-abdominal-wall:s0":{"s":0,"u":["The abdomen contains intraperitoneal and retroperitoneal organs within a wall of overlapping muscle and connective tissue: the anterolateral wall , the inguinal canal and the posterior wall .","The wall protects the viscera, maintains their position, helps raise abdominal pressure (coughing, defecation, childbirth) and moves the trunk."],"dp":[]},"anat2-abdominal-wall:e0":{"s":1,"u":["Rule of 3: skin, Camper's, Scarpa's / EO, IO, TA / transversalis fascia, extraperitoneal fat, peritoneum.","Rule of 3 (lateral to rectus): 3 layers above the muscles (skin, fatty Camper's fascia , membranous Scarpa's fascia ), 3 flat muscles ( external oblique , internal oblique , transversus abdominis ) and 3 layers below ( transversalis fascia , extraperitoneal fat, parietal peritoneum )."],"dp":[{"h":"Note","t":"Rule of 3 : skin, Camper's (fatty), Scarpa's (membranous) → external oblique, internal oblique, transversus → transversalis fascia, extraperitoneal fat, peritoneum."}]},"anat2-abdominal-wall:e2":{"s":1,"u":["IO gives cremaster; IO + TA = conjoint tendon.","The internal oblique gives the cremaster muscle along the spermatic cord and, with transversus, the conjoint tendon ."],"dp":[]},"anat2-abdominal-wall:e3":{"s":1,"u":["Rectus sheath; linea alba; arcuate line: no posterior sheath below.","The flat muscles' aponeuroses form the rectus sheath and meet at the linea alba ; below the arcuate line the posterior sheath is missing and only transversalis fascia lies behind rectus."],"dp":[{"h":"Note","t":"Arcuate line : below it all aponeuroses pass in front of rectus; only transversalis fascia lies behind it."}]},"anat2-abdominal-wall:e4":{"s":1,"u":["Umbilical remnants: round ligament, median and medial umbilical ligaments.","Umbilicus : umbilical vein → round ligament of the liver; urachus → median umbilical ligament; umbilical arteries → medial umbilical ligaments.","Weak areas : umbilicus ( umbilical hernia ), linea semilunaris ( Spigelian hernia ), surgical incisions."],"dp":[{"h":"Note","t":"Umbilical remnants : umbilical vein → ligamentum teres ; urachus → median umbilical ligament; umbilical arteries → medial umbilical ligaments."}]},"anat2-abdominal-wall:e5":{"s":1,"u":["Lymph above umbilicus → axillary; below → superficial inguinal.","Lymph : superficially, above the umbilicus to axillary nodes and below it to superficial inguinal nodes; deeply to internal thoracic, lumbar and external iliac nodes.","The external oblique's lower edge forms the inguinal ligament and its aponeurosis the superficial (external) inguinal ring ."],"dp":[{"h":"Clinical","t":"Skin lymph: above the umbilicus → axillary nodes, below → superficial inguinal . Weak spots: umbilicus, linea semilunaris (Spigelian), incisions."}]},"anat2-abdominal-wall:e6":{"s":1,"u":["Weak areas: umbilicus, linea semilunaris (Spigelian), incisions.","Weak areas : umbilicus ( umbilical hernia ), linea semilunaris ( Spigelian hernia ), surgical incisions.","Vertical muscles: rectus abdominis (bounded laterally by the linea semilunaris ) and the small pyramidalis ."],"dp":[]},"anat2-abdominal-wall:e1":{"s":2,"u":["EO lower edge = inguinal ligament; aponeurosis = superficial ring.","It runs from the deep ring (opening in the transversalis fascia, lateral to the inferior epigastric vessels) to the superficial ring (in the external oblique aponeurosis, above the pubic tubercle).","Walls: anterior , external oblique aponeurosis (+ internal oblique laterally); posterior , transversalis fascia (+ conjoint tendon medially); roof , arching fibres of internal oblique and transversus; floor , inguinal ligament (+ lacunar ligament medially)."],"dp":[{"h":"Memory aid","t":"Canal walls 'MALT' from above round: roof = M uscles (IO, TA arches); anterior = A poneurosis of EO; floor = L igament (inguinal); posterior = T ransversalis fascia (+ conjoint tendon)."}]},"anat2-abdominal-wall:e7":{"s":2,"u":["Inguinal canal: deep ring (transversalis fascia) → superficial ring (EO).","It runs from the deep ring (opening in the transversalis fascia, lateral to the inferior epigastric vessels) to the superficial ring (in the external oblique aponeurosis, above the pubic tubercle).","Indirect inguinal hernias enter the deep ring, lateral to the inferior epigastric vessels; direct hernias push through the posterior wall medial to them."],"dp":[{"h":"Note","t":"Inguinal canal (~4 cm): deep ring in transversalis fascia (lateral to the inferior epigastric vessels) → superficial ring in the external oblique aponeurosis (above the pubic tubercle). Contents: spermatic cord / round ligament + ilio-inguinal nerve ."}]},"anat2-abdominal-wall:e8":{"s":2,"u":["Contents: spermatic cord / round ligament, ilio-inguinal nerve.","Contents: spermatic cord in males, round ligament of the uterus in females, plus the ilio-inguinal nerve and the genital branch of the genitofemoral nerve."],"dp":[]},"anat2-abdominal-wall:e9":{"s":2,"u":["Indirect hernia lateral, direct medial to inferior epigastric vessels.","Indirect inguinal hernias enter the deep ring, lateral to the inferior epigastric vessels; direct hernias push through the posterior wall medial to them.","It runs from the deep ring (opening in the transversalis fascia, lateral to the inferior epigastric vessels) to the superficial ring (in the external oblique aponeurosis, above the pubic tubercle)."],"dp":[{"h":"Why indirect inguinal hernias are common in boys","t":"The testis descends through the inguinal canal before birth, dragging a pouch of peritoneum (the processus vaginalis) with it. If this pouch fails to close, it leaves an open path from the abdomen through the deep ring into the scrotum. Bowel can slip down that path, lateral to the inferior epigastric vessels: an indirect hernia, the most common type, especially in male infants. Source: the lecture's inguinal canal embryology and hernia slides."},{"h":"Note","t":"Indirect hernia: through the deep ring, lateral to the inferior epigastric vessels (can reach the scrotum; common in young males). Direct : through the posterior wall, medial to them, in Hesselbach's triangle (older men)."}]},"anat2-abdominal-wall:e10":{"s":3,"u":["Posterior wall: psoas, quadratus lumborum, iliacus, diaphragm.","Muscles: medially psoas major (and minor), laterally quadratus lumborum , inferiorly iliacus (joins psoas as iliopsoas, the main hip flexor), superiorly the diaphragm ."],"dp":[{"h":"Clinical","t":"Iliopsoas on the posterior wall: an inflamed retrocaecal appendix or psoas abscess gives pain on hip extension ( psoas sign )."}]}},"meta":{"9rasgc":{"a":"recall","vg":"anat2-abdominal-wall:e0/recall/1"},"fkn486":{"a":"recall","vg":"anat2-abdominal-wall:e7/recall/1"},"1vdzvzu":{"a":"recall","vg":"anat2-abdominal-wall:e1/recall/1"},"40v04e":{"a":"recall","vg":"anat2-abdominal-wall:e2/recall/1"},"1m4ylji":{"a":"recall","vg":"anat2-abdominal-wall:e3/recall/1"},"nlh76a":{"a":"recall","vg":"anat2-abdominal-wall:e4/recall/1"},"kw8vmf":{"a":"recall","vg":"anat2-abdominal-wall:e5/recall/1"},"6dczac":{"a":"recall","vg":"anat2-abdominal-wall:e6/recall/1"},"1ndf0lk":{"a":"recall","vg":"anat2-abdominal-wall:e7/recall/2"},"ek316v":{"a":"recall","vg":"anat2-abdominal-wall:e1/recall/2"},"qacv87":{"a":"recall","vg":"anat2-abdominal-wall:e8/recall/1"},"fuvnx8":{"a":"recall","vg":"anat2-abdominal-wall:e7/recall/3"},"1q4hwdj":{"a":"recall","vg":"anat2-abdominal-wall:e10/recall/1"}},"explRev":"7c3dfc5b451a"};
